src, dst = sys.argv[1], sys.argv[2]
t = open(src, encoding="utf-8").read()
missing = []
for old, new, n in R:
    c = t.count(old)
    if c != n:
        missing.append((c, n, old[:90]))
        continue
    t = t.replace(old, new)
if missing:
    for c, n, o in missing:
        print(f"MISMATCH found {c} expected {n}: {o}")
    sys.exit(1)
open(dst, "w", encoding="utf-8").write(t)
print("applied", len(R), "rewrites")
